    'permission_manage_customer_class_passes_description' => 'Edit customer passes, payments, freezes, validity, and adjustment history.',
    'permission_correct_closed_classes_description' => 'Add or remove customers from already-ended classes, remove bookings during a closed cancellation window, and change consumed pass sessions.',
    'permission_record_customer_payments_description' => 'Record point cash payments for classes and passes without access to finance pages.',
    'permission_manage_studio_cashflow_description' => 'Reconcile cashboxes, record expenses, deposits, and withdrawals without access to general reports.',
    'permission_view_studio_financial_reports_description' => 'View payment history, financial, earnings, and rental reports.',
    'permission_manage_studio_payroll_description' => 'Configure salary models and close or void payroll periods.',
    'permission_view_activity_log_description' => 'View account activity and audit events.',
    'permission_mark_attendance_description' => 'Mark bookings as attended, no-show, cancelled, or booked.',
    'permission_manage_trainers_description' => 'Create trainers, staff logins, substitutions, and trainer permissions.',
    'permission_manage_studio_settings_description' => 'Edit studio rooms, locations, formats, integrations, and brand settings.',
    'permission_manage_schedule_details' => 'Allows creating recurring schedules and one-off classes; changing the time, room, format, or trainer; and cancelling or restoring schedule entries. Cancelling a class that already has bookings also requires the booking permission.',
    'permission_manage_clients_details' => 'Allows opening the customer list and profiles, creating and editing customer contact data, and using customer import and export tools. It does not grant permission to issue or edit purchased class passes.',
    'permission_manage_bookings_details' => 'Allows searching for customers, adding them to group classes, creating quick bookings for private lessons or rentals, changing booking statuses, and cancelling inside the normal cancellation window. Changes after the class or cutoff require the closed-class correction permission.',
    'permission_manage_website_leads_details' => 'Allows viewing incoming website enquiries, creating or updating lead records, changing their status, and converting them into studio customers. It does not grant general access to all customer profiles.',
    'permission_interact_with_telegram_bot_details' => 'Allows using the connected owner assistant and authorized Telegram workflows for this studio. Individual sensitive actions still require their matching schedule, customer, pass, finance, payroll, or event permission.',
    'permission_issue_customer_class_passes_details' => 'Allows issuing a new purchased class pass from an active plan, recording its initial paid amount, and matching eligible existing bookings to the pass. It does not allow later validity, freeze, status, or session-balance corrections.',
    'permission_manage_customer_class_passes_details' => 'Allows opening purchased class passes, changing their status and lifecycle dates, freezing or unfreezing them, reconciling bookings, and recording session or validity adjustments with a reason. Recording a new point payment requires the separate customer-payment permission.',
    'permission_correct_closed_classes_details' => 'Allows backdated corrections after a class ends or its cancellation window closes: adding or removing customers, cancelling closed classes or bookings, and correcting consumed pass sessions. These changes alter historical booking and pass records.',
    'permission_record_customer_payments_details' => 'Allows recording point payments for unpaid class bookings and manually issued class passes. It does not grant access to payment reports, cashbox reconciliation, expenses, deposits, or withdrawals.',
    'permission_manage_studio_cashflow_details' => 'Allows opening cashbox and expense pages, reconciling counted cash, managing expense categories, and recording expenses, deposits, or withdrawals. It does not grant access to general payment, earnings, rental, or payroll reports.',
    'permission_view_studio_financial_reports_details' => 'Allows viewing payment history plus financial, earnings, private-lesson, and rental reports. It is reporting access and does not by itself allow cashbox operations, expense changes, or payroll-period management.',
    'permission_manage_studio_payroll_details' => 'Allows viewing trainer salary details, assigning and configuring salary models, setting payroll cadence, and closing or voiding payroll periods. These actions change the studio’s payroll records.',
    'permission_view_activity_log_details' => 'Allows viewing the studio activity log and related customer-notification and Telegram-alert delivery logs. It exposes who performed recorded actions but does not grant permission to repeat those actions.',
    'permission_mark_attendance_details' => 'Allows changing a booking status to attended, no-show, cancelled, or booked from schedule and dashboard cards. It does not allow creating schedule entries or editing customer profiles.',
    'permission_manage_trainers_details' => 'Allows creating and editing trainer profiles, locations, directions, private timeframes, staff logins, substitutions, and other trainers’ permissions. A trainer with this right can change another staff member’s access.',
    'permission_manage_studio_settings_details' => 'Allows changing studio locations, rooms, directions, class formats, service rooms, integrations, API tokens, notification settings, and brand-related configuration. It can affect how the whole studio operates.',
